document.addEventListener("DOMContentLoaded",()=>{const e=document.getElementById("nl-progress-fill"),t=()=>{const t=window.scrollY,n=document.documentElement.scrollHeight-window.innerHeight,o=n>0?t/n*100:0;e&&(e.style.width=`${o}%`)};window.addEventListener("scroll",t,{passive:!0}),t(),document.querySelectorAll(".nl-toc a").forEach(e=>{e.addEventListener("click",t=>{const n=document.querySelector(e.getAttribute("href"));n&&(t.preventDefault(),n.scrollIntoView({behavior:"smooth"}))})})});